368:   function findBestCandidate(currentElement, direction, candidates) {
369:     var dir = normalizeDirection(direction);
370:     if (!dir || !currentElement) return null;
371: 
372:     // Transitioning down from fixed header into the active view prefers the view's default anchor
373:     if (dir === 'down' && currentElement.closest && currentElement.closest(CONFIG.headerSelector)) {
374:       var activeView = document.querySelector(CONFIG.activeViewSelector);
375:       if (activeView) {
376:         var defaultEl = activeView.querySelector('[data-nav-default="true"]');
377:         if (defaultEl && isNavigable(defaultEl)) {
