383:     var currentRect = currentElement.getBoundingClientRect();
384:     var list = candidates || getCandidates();
385:     if (!list || !list.length) return null;
386: 
387:     var strictTan = Math.tan((CONFIG.strictConeAngle * Math.PI) / 180);   // ~1.732 for 60 deg
388:     var fallbackTan = Math.tan((CONFIG.fallbackConeAngle * Math.PI) / 180); // ~11.43 for 85 deg
389: 
390:     // Pass 1: Strict Angle Cone (60 degrees)
391:     var best = null;
392:     var bestRes = null;
393: 
394:     for (var i = 0; i < list.length; i++) {
395:       var cand = list[i];
396:       if (cand === currentElement) continue;
397: 
398:       var candRect = cand.getBoundingClientRect();
399:       if (candRect.width <= 0 || candRect.height <= 0) continue;
400: 
401:       var res = computeGeometricScore(currentRect, candRect, dir, strictTan);
402:       if (res.qualified) {
403:         if (!bestRes || res.score < bestRes.score) {
404:           best = cand;
405:           bestRes = res;
406:         } else if (Math.abs(res.score - bestRes.score) < 1.0) {
407:           // Tie-breaking: Tier 1 Overlap -> Tier 2 Euclidean -> Tier 3 DOM Order
408:           if (res.overlap > bestRes.overlap) {
409:             best = cand;
410:             bestRes = res;
411:           } else if (res.overlap === bestRes.overlap) {
412:             if (res.euclidean < bestRes.euclidean) {
413:               best = cand;
414:               bestRes = res;
415:             } else if (res.euclidean === bestRes.euclidean) {
416:               if (currentElement.compareDocumentPosition &&
417:                   (best.compareDocumentPosition(cand) & Node.DOCUMENT_POSITION_PRECEDING)) {
418:                 best = cand;
419:                 bestRes = res;
420:               }
421:             }
422:           }
423:         }
424:       }
425:     }
426: 
427:     if (best) return best;
428: 
429:     // Pass 2: Fallback Cone (85 degrees)
430:     for (var j = 0; j < list.length; j++) {
431:       var cand2 = list[j];
432:       if (cand2 === currentElement) continue;
433: 
434:       var candRect2 = cand2.getBoundingClientRect();
435:       if (candRect2.width <= 0 || candRect2.height <= 0) continue;
436: 
437:       var res2 = computeGeometricScore(currentRect, candRect2, dir, fallbackTan);
438:       if (res2.qualified) {
439:         if (!bestRes || res2.score < bestRes.score) {
440:           best = cand2;
441:           bestRes = res2;
442:         } else if (Math.abs(res2.score - bestRes.score) < 1.0) {
443:           if (res2.overlap > bestRes.overlap) {
444:             best = cand2;
445:             bestRes = res2;
446:           } else if (res2.overlap === bestRes.overlap && res2.euclidean < bestRes.euclidean) {
447:             best = cand2;
448:             bestRes = res2;
449:           }
450:         }
451:       }
452:     }
453: 
454:     return best;
455:   }
